/** @jsxImportSource react */
import type { SliderPreviewOverflow } from '@videojs/core';
import { cn, resolveClassName } from '@videojs/utils/style';

import { TimeSlider } from '../../../../../../skin-primitives';
import { SliderBuffer, SliderFill, SliderThumb, SliderTrack } from '../../../../components/sliders/slider';

export interface AudioTimeSliderProps extends Omit<TimeSlider.RootProps, 'children'> {
  previewOverflow?: SliderPreviewOverflow | undefined;
}

export function AudioTimeSlider({ className, previewOverflow = 'clamp', ...props }: AudioTimeSliderProps = {}) {
  return (
    <TimeSlider.Root
      className={(state) => cn('media-slider', 'audio-time-slider', resolveClassName(className, state))}
      {...props}
    >
      <TimeSlider.Track render={<SliderTrack />}>
        <TimeSlider.Buffer render={<SliderBuffer />} />
        <TimeSlider.Fill render={<SliderFill />} />
      </TimeSlider.Track>
      <TimeSlider.Thumb render={<SliderThumb />} className={'audio-time-slider-thumb'} />
      <TimeSlider.Preview className={'media-slider-preview'} overflow={previewOverflow}>
        <div
          className={cn(
            'media-slider-preview-content',
            'media-popup-surface',
            'media-tooltip',
            'audio-time-slider-preview-content'
          )}
        >
          <TimeSlider.Value className={'audio-time-slider-value'} type="pointer" />
        </div>
      </TimeSlider.Preview>
    </TimeSlider.Root>
  );
}
